with kept as (select s.* from orders s where not exists (select 1 from order_items ch where ch.order_id = s.id and ch.order_id in (5, 13, 36))) select date_trunc('month', order_date) as activity_month, count_if(channel = 'web') as web_events, round(sum(shipping_fee) / nullif(count(case when channel = 'partner' then 1 end), 0), 2) as shipping_fee_per_partner, count(distinct channel) as distinct_channels from kept group by cube (date_trunc('month', order_date)) having round(sum(shipping_fee) / nullif(count(case when channel = 'partner' then 1 end), 0), 2) >= 0 order by shipping_fee_per_partner desc nulls last
